import{_ as s,o as a,c as i,aw as e}from"./chunks/framework.DLufY-ao.js";const p=JSON.parse('{"title":"WebRTC","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/network/network/tech/webrtc.md","filePath":"wiki/dev-commit/network/network/tech/webrtc.md"}'),t={name:"wiki/dev-commit/network/network/tech/webrtc.md"};function o(r,l,c,n,u,m){return a(),i("div",null,[...l[0]||(l[0]=[e(`<h1 id="webrtc" tabindex="-1">WebRTC <a class="header-anchor" href="#webrtc" aria-label="Permalink to &quot;WebRTC&quot;">​</a></h1><h2 id="информация" tabindex="-1">Информация <a class="header-anchor" href="#информация" aria-label="Permalink to &quot;Информация&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">INFO</p><ul><li><a href="https://www.youtube.com/watch?v=R0wcvVYst-M" target="_blank" rel="noreferrer">https://www.youtube.com/watch?v=R0wcvVYst-M</a></li></ul></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li><strong>WebRTC</strong> (real-time communications - коммуникации в реальном времени) - проект, предназначенный для организации передачи потоковых данных между браузерами или другими поддерживающими его приложениями по технологии точка-точка</li></ul></div><ul><li>Технология WebRTC делает возможной видеосвязь через окно браузера, так что для присоединения к звонку необходимо только перейти по ссылке на соответствующую веб-страницу</li><li>В WebRTC используются два аудиокодека, G.711 и Opus, а также видеокодеки VP8 и H.264</li><li>Хотя WebRTC изначально рассчитано на соединения типа точка-точка и peer-to-peer, существует несколько готовых реализаций WebRTC-серверов, организующих сложные групповые конференции между разными браузерами. Такие серверы также обеспечивают присоединение к связи с браузерами сторонних устройств - IP-камер, использующих протокол RTSP/RTP, а также SIP и H.323-терминалов</li><li>Просмотр в Chrome <em>chrome://webrtc-internals/</em></li></ul><h2 id="пример-использования" tabindex="-1">Пример использования <a class="header-anchor" href="#пример-использования" aria-label="Permalink to &quot;Пример использования&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p><strong><code>navigator. getUserMedia (constraints)</code></strong> - получение доступа к устройствам</p><blockquote><ul><li><code>constraints</code> - объект, содераший вид устройства (аудио, видео или оба)</li><li><em>return</em> - возвращает Promise, который, в случае согласия пользователя, разрешается MediaStream объектом. Если пользователь отказывает в разрешении, или медиа устройсто не доступно, тогда промис отменяется с объектами типа NotAllowedError или NotFoundError соответственно</li></ul></blockquote></div><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#383A42;">navigator.</span><span style="color:#E45649;">mediaDevices</span></span>
<span class="line"><span style="color:#383A42;">  .</span><span style="color:#4078F2;">getUserMedia</span><span style="color:#383A42;">(constraints)</span></span>
<span class="line"><span style="color:#383A42;">  .</span><span style="color:#4078F2;">then</span><span style="color:#383A42;">((stream) </span><span style="color:#A626A4;">=&gt;</span><span style="color:#383A42;"> {</span></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">    // Используем поток</span></span>
<span class="line"><span style="color:#383A42;">  })</span></span>
<span class="line"><span style="color:#383A42;">  .</span><span style="color:#4078F2;">catch</span><span style="color:#383A42;">((err) </span><span style="color:#A626A4;">=&gt;</span><span style="color:#383A42;"> {</span></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">    // Обработка ошибки</span></span>
<span class="line"><span style="color:#383A42;">  });</span></span></code></pre></div><h2 id="преимущества-и-недостатки" tabindex="-1">Преимущества и недостатки <a class="header-anchor" href="#преимущества-и-недостатки" aria-label="Permalink to &quot;Преимущества и недостатки&quot;">​</a></h2><p><strong>Преимущества</strong></p><ul><li>Проведение конференции в браузере значительно упрощает процесс проведения конференции — пользователю не нужно устанавливать для этого отдельные приложения</li><li>Используемые кодеки обеспечивают хорошее качество связи</li><li>Возможность реализации любых элементов интерфейса средствами HTML5 и JavaScript</li><li>Открытый исходный код даёт больше возможностей для использования</li></ul><p><strong>Недостатки</strong></p><ul><li>Технология определяет только общий стандарт передачи данных (видео и звука), но отдельные решения разных браузеров относительно адресации абонентов и прочих управляющих процессов не совместимы между собой. Поэтому даже звонки между парой различных браузеров представляют отдельную сложность</li><li>Обеспечение групповых конференций требует дополнительных разработок поверх WebRTC</li></ul><h2 id="_7-шагов" tabindex="-1">7 шагов <a class="header-anchor" href="#_7-шагов" aria-label="Permalink to &quot;7 шагов&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li><strong>TCP</strong> - WebSocket</li><li><strong>UDP</strong> - WebRTC (+Media, +P2P)</li></ul></div><details class="details custom-block"><summary>1. Захват камеры</summary><ol><li>Получаем объект <code>MediaStream</code> из <code>navigator.getUserMedia</code></li><li>Размер чистого потока:</li></ol><ul><li>Изображение 640x480, 32bit: 1.2mb</li><li>30 кадров, 1 секунда: 36mb</li><li>Битрейт: 288mbps</li></ul></details><details class="details custom-block"><summary>2. Кодирование - сжаие аудио и видео потоков</summary><ul><li>JPEG, 640x480 <ul><li>1.2mb -&gt; 123kb</li><li>288mbps -&gt; 28mbps</li></ul></li><li>VP9, 1280x720 — 1.5mbps</li><li>Диффы, keyframe, interframe</li></ul></details><details class="details custom-block"><summary>3. Запаковка в RTP</summary><ul><li>Порядок - пакеты могут приходить в разном порядке</li><li>Время - хранит информацию про время чтобы синхронизировать аудио и видео дорожку</li><li>Треки</li><li>Оверхед: ~5% (62 / 1204)</li><li><strong>RTCP (RPT Control Protocol)</strong> - обмен информацией про потярянные пакеты, статистика их получения и т.д. Расширение основного протокола</li></ul></details><details class="details custom-block"><summary>4. Передача по сети через UDP</summary><ul><li>Главный плюс UDP: <ul><li>Минимальный интервал между пакетами</li></ul></li><li>Минусы UDP <ul><li>Пакеты теряются</li><li>Пакеты приходят поздно</li><li>Пакеты приходят в другом порядке</li></ul></li></ul></details><details class="details custom-block"><summary>5. Распаковка RTP</summary><ol><li>Восстанавливаем порядок</li><li>Достаем видео-трафик</li><li>Передаем в декодер</li></ol></details><details class="details custom-block"><summary>6. Декодирование</summary><ol><li>Передаем данные в правильном порядке</li><li>На выходе - чистый видео-поток - <code>MediaStream</code></li></ol></details><details class="details custom-block"><summary>7. Отрисовка на экране <code>&lt;video&gt;</code></summary><ul><li>Прикрепляем поток к элементу и получаем картинку</li></ul></details><h2 id="потери-пакетов" tabindex="-1">Потери пакетов <a class="header-anchor" href="#потери-пакетов" aria-label="Permalink to &quot;Потери пакетов&quot;">​</a></h2><ul><li>Остаются в стенах дома - Random loss или Lossy network</li><li>Дропаются по ошибке: баги в ОС или сетевом оборудовании</li><li>Дропаются из-за перегрузки сети - Network congestion</li></ul><details class="details custom-block"><summary>Решение №1: Jitter buffer: рендерим позже, даем себе время на повторный запрос</summary><ul><li>Минус: дополнительная постоянная задержка</li><li>Плюсы: <ul><li>Есть время запросить недостающий пакет</li><li>При массовой потере, больше времени на запрос keyframe</li></ul></li></ul></details><details class="details custom-block"><summary>Решение №2: Уменьшаем битрейт, деградируем качество</summary><ul><li>Битрейт = FPS _ качество _ разрешение</li><li>Минусы: <ul><li>Хуже качество (временно)</li><li>Не поможет с random loss</li></ul></li><li>Плюс: поможет с network congestion</li></ul></details><details class="details custom-block"><summary>Решение №3: Forward Error Correction</summary><ul><li>Умное дублирование данных на уровне кодека</li><li>Минус: выше битрейт — усугубляет network congestion</li><li>Плюс: выше шанс доставки контента с первого раза</li></ul></details><details class="details custom-block"><summary>Решение №4: Сетевой тюнинг</summary><ul><li>Лучшие сетевые маршруты</li><li>Настройка серверов и маршрутизаторов</li></ul></details>`,28)])])}const b=s(t,[["render",o]]);export{p as __pageData,b as default};
